// build-index.js, and a skipped message that DID carry a QU is logged with its code so the
// omission is discoverable in the execution list rather than silent.
const POST_ENGINEERS = {
  'U025597KZ':   'regie',
  'U029T6N7U':   'philip',
  'U026N6E1R':   'tara',
  'U04DLRCAA':   'glenn',
  'U6UAKUP08':   'whannie',
  'U026LMLM4':   'rico',
  'U026N9FV9':   'vener',
  'U026N7KR7':   'topet',
  'U026MTBLM':   'richard',
  'U026R9SUQ':   'eddie boy',
  'U08V83R45QV': 'elijah',
