// Build the {digits -> quote} lookup from the Xero responses. Each response is the body
// of one GET /Quotes?QuoteNumber=… call, so it carries a Quotes array with 0 or 1 (rarely
// more) quotes. A candidate whose QU is absent here is NOT_FOUND. DELETED quotes are
// dropped — a deleted quote is not a live project and must not vouch for a mistyped QU.
function indexQuotes(responses) {
  const byDigits = {};
  for (const resp of (responses || [])) {
    const quotes = (resp && (resp.Quotes || (resp.body && resp.body.Quotes))) || [];
    for (const q of quotes) {
      if (!q) continue;
      const status = cellText(q.Status).toUpperCase();
      if (status === 'DELETED') continue;
      const d = quDigits(cellText(q.QuoteNumber));
      if (!d) continue;
      if (!(d in byDigits)) {
        byDigits[d] = {
          quoteNumber: cellText(q.QuoteNumber),
          client: q.Contact ? cellText(q.Contact.Name) : '',
          status: cellText(q.Status),
          hours: studioHoursDetail(q.LineItems),
        };
        const h = byDigits[d].hours;
        // Public only when the booked hours are clear; otherwise Tara checks them (hoursToCheck).
        byDigits[d].studioHours = h.clear ? h.total : null;
        byDigits[d].hoursToCheck = h.figures.length && !h.clear ? h.figures : null;
      }
    }
  }
  return byDigits;
}

// Xero answering is not the same as Xero saying "no such quote". A real lookup always returns a
// Quotes array, empty when the number doesn't exist. Anything else (an expired connection, a 401,
// a 5xx, a rate limit) has no Quotes array, and indexQuotes would read that as "not found" and
// post a false typo flag on every post (2026-09-28). This returns the failed responses so the run
// can stop before posting anything. The first one's error text goes to Tara.
function failedLookups(responses) {
  const bad = [];
  for (const resp of (responses || [])) {
    const q = resp && (resp.Quotes || (resp.body && resp.body.Quotes));
    if (!Array.isArray(q)) bad.push(resp);
  }
  return bad;
}

function xeroDownText(bad, ctx) {
  const c = ctx || {};
  const r = bad[0] || {};
  const why = String(r.Detail || r.Title || r.message || r.error || (r.Status ? 'HTTP ' + r.Status : '') || 'no answer')
    .replace(/\s+/g, ' ').slice(0, 140);
  return '*Typo check — ' + (c.dateLabel || 'today') + '*\n' +
    "⚠️ Couldn't reach Xero (" + bad.length + ' of ' + (c.checked || bad.length) + ' lookups failed: ' + why + ').\n' +
    (c.mode === 'preview'
      ? 'Nothing was checked.'
      : 'Nothing was posted, and these posts will be checked again next run.') +
    '\nIf this repeats, the Xero connection needs re-authorizing: someone with Standard or Adviser ' +
    'access in Xero clicks *Connect* on the n8n "Xero account" credential.';
}

// Has Posty already replied in this post's thread? Every post is checked the moment it's posted
// (live) AND again by the 09:00/17:00 safety-net runs, and Slack sometimes delivers an event twice,
// so the thread itself is the record of "done". resp is one conversations.replies body; messages[0]
// is the post, the rest are replies. A failed read counts as not replied, so the post is still checked.
const POSTY_USER = 'U0BTV2PGDSM', POSTY_BOT = 'B0BTLTJQD6F';
function alreadyReplied(resp) {
  if (!resp || resp.ok !== true) return false;
  return (resp.messages || []).slice(1).some((m) => m && (m.user === POSTY_USER || m.bot_id === POSTY_BOT));
}

// One post that carries a real QU. Built by gatherCandidates. Shape:
//   { qu, quDisplay, ts, channel, text }
//
// helpers is the parse.js surface, injected so this module stays require-free when pasted
// into an n8n node: { isPostEngineer, extractQu, decodeEntities, tsToDate, isIntakeWorkflow,
// submitterFromText, cleanWorkflowText }.
//
// A post counts as a project either because a post engineer wrote it OR because it came from
// the "New Project" intake form — which now posts as a bot with no `user`, so without the
// isIntakeWorkflow branch the typo check would silently skip every form post, i.e. the whole
// point of the check on the primary intake path. Form posts contribute the cleaned line and
// the submitter is irrelevant here (we only validate the QU + client).
//
// dateFilter is optional. The window is really bounded by the Slack `oldest` the caller
// fetched with — either midnight today (preview) or the since-last-checked watermark
// (scheduled). Pass a YYYY-MM-DD to additionally keep only that day's posts; pass null to
// keep everything the fetch returned, which is what the watermark path wants (its window
// can legitimately span more than one day if a run was missed).
function gatherCandidates(messages, dateFilter, helpers) {
  const out = [];
  const seen = {};
  for (const m of (messages || [])) {
    if (!m) continue;
    const wf = typeof helpers.isIntakeWorkflow === 'function' && helpers.isIntakeWorkflow(m);
    let text, poster;
    if (wf) {
      // A form post comes from the bot; the person to tag is the submitter it names.
      poster = typeof helpers.submitterFromText === 'function' ? helpers.submitterFromText(m.text) : '';
      text = typeof helpers.cleanWorkflowText === 'function' ? helpers.cleanWorkflowText(m.text) : (m.text || '');
    } else {
      if (m.subtype) continue;                       // joins, leaves, non-intake bot posts
      if (!helpers.isPostEngineer(m.user)) continue; // only announcements, excludes Posty
      text = helpers.decodeEntities(m.text || '');
      poster = m.user || '';
    }
    const qu = helpers.extractQu(text);              // null for no-code / QU- placeholder
    if (!qu) continue;
    if (dateFilter && helpers.tsToDate(m.ts) !== dateFilter) continue; // preview only
    if (seen[qu]) continue;                          // same code posted twice, check once
    seen[qu] = true;
    out.push({
      qu: qu,
      quDisplay: 'QU-' + qu,
      ts: String(m.ts),
      channel: m.channel || '',
      text: text,
      poster: /^[UW][A-Z0-9]+$/.test(String(poster || '')) ? String(poster) : '',
    });
  }
  return out;
}

// Existence-only against Xero. A Xero quote has no agency or producer field, and its
// customer (Contact) is the parent client (Unilever for a Knorr project), so matching it to
// the post cried wolf constantly — dropped 2026-09-17 (Tara). The only Xero signal is
// whether the QU is a real quote number at all: found -> ok, absent -> notFound (the public
// typo flag). `mismatch` is kept empty so the summary and findings count stay uniform.
function classifyXero(candidates, byDigits) {
  const notFound = [], ok = [];
  for (const c of (candidates || [])) {
    if (byDigits[c.qu]) {
      const q = byDigits[c.qu], h = q.hours || {};
      ok.push(Object.assign({}, c, { studioHours: q.studioHours, hoursToCheck: q.hoursToCheck || null,
        hoursBreakdown: q.studioHours != null ? (h.breakdown || '') : '', hoursOptional: q.studioHours != null ? h.optional : null }));
    }
    else notFound.push(c);
  }
  return { notFound: notFound, mismatch: [], ok: ok };
}

// The public in-thread reply. mrkdwn (single-asterisk bold). Gentle by design: it
// asks for a check, it does not assert the poster is wrong — Xero can lag a little,
// and a false accusation in the intake channel is exactly what erodes trust in Posty.
// "the database" rather than "Xero" — the source is kept generic in what people see
// (Tara, 2026-09-17). Only the messages use this wording; the code still checks Xero.
// Public replies tag the poster so they get a notification: a thread reply alone only reaches
// people following the thread, and a form post's thread belongs to the bot (Tara, 2026-09-28).
function tag(c) { return c && c.poster ? '<@' + c.poster + '> ' : ''; }

function flagText(c) {
  // Specific next steps (Tara, 2026-09-28): repost with the right QU, and leave the old post. Form
  // posts can't be deleted by engineers, Tara removes them, and there's no rush: the repost has a
  // different QU, so it is tracked on its own either way.
  return tag(c) + c.quDisplay + " isn't in the database — mind double-checking? " +
    "If it's a typo, please post the project again with the correct QU. " +
    "No need to delete this one, Tara will remove it. If the QU is correct, just ignore this.";
}

// The public studio-hours reply, for a found quote that names its hours. Same wording rule as
// flagText: "the quote", never "Xero".
function fmtHours(h) { return h + (h === 1 ? ' hr' : ' hrs'); }
// "(30 TV + 10 Radio)" for a media split, "(+ 4 hrs optional)" for an optional offer on the quote.
function hoursExtra(c) {
  return (c.hoursBreakdown ? ' (' + c.hoursBreakdown + ')' : '') +
    (c.hoursOptional != null ? ' (+ ' + fmtHours(c.hoursOptional) + ' optional)' : '');
}
function hoursText(c) {
  return tag(c) + '🎧 Studio hours based on ' + c.quDisplay + ': *' + fmtHours(c.studioHours) + '*' + hoursExtra(c);
}

// The post text with the leading QU token stripped, so a summary line can read
// "QU-71498 — OMT / Producer / Title" without repeating the code.
function afterQu(text) {
  const t = firstLine(text);
  const idx = t.indexOf('/');
  return idx !== -1 ? t.slice(idx + 1).trim() : t;
}

// Tara's DM summary. mode is 'scheduled' or 'preview'. In preview nothing was posted
// publicly, so the summary says what *would* post. res is classify()'s result.
function buildTaraSummary(res, ctx) {
  const c = ctx || {};
  // live = one post checked the moment it was posted (Workflow 2 calls in, 2026-09-28).
  const mode = c.mode === 'preview' || c.mode === 'live' ? c.mode : 'scheduled';
  const checked = c.checked == null ? 0 : c.checked;
  const already = c.already || [];
  const day = c.dateLabel || '';
  const lines = [];
  const would = mode === 'preview';

  if (mode === 'live') {
    const x = res.notFound[0] || res.ok[0];
    lines.push('*Typo check — new post' + (x ? ', ' + x.quDisplay : '') + '*');
  } else {
    lines.push(would
      ? '*Typo check — ' + (day || 'today') + '*  (preview — nothing posted publicly)'
      : '*Typo check — ' + (day || 'today') + '*');
    // Runs twice a day on a watermark, so a scheduled run covers "since the last check", not
    // "this morning" (the 17:00 run said "from this morning" until 2026-09-26). Posts already
    // answered when they were posted are counted separately and never replied to twice.
    lines.push('Checked ' + checked + ' post' + (checked === 1 ? '' : 's') +
      (would ? ' posted today' : ' since the last check') +
      (already.length ? ' (' + already.length + ' more already replied to when posted)' : '') + '.');
  }

  if (res.notFound.length) {
    lines.push('');
    lines.push(would
      ? "🔴 *Not in the database* — I'd reply on these posts:"
      : '🔴 *Not in the database* — replied on these posts:');
    res.notFound.forEach((x, i) => lines.push((i + 1) + '. ' + x.quDisplay + ' — ' + afterQu(x.text)));
  }

  if (!res.notFound.length && checked) {
    lines.push('');
    lines.push(mode === 'live' ? '✅ The QU is in the database.' : '✅ All clear — every QU is in the database.');
  }

  const withHours = res.ok.filter((x) => x.studioHours != null);
  const toCheck = res.ok.filter((x) => x.hoursToCheck);
  const noHours = res.ok.filter((x) => x.studioHours == null && !x.hoursToCheck);
  if (withHours.length) {
    lines.push('');
    lines.push(would
      ? "🎧 *Studio hours* — I'd reply on these posts:"
      : '🎧 *Studio hours* — replied on these posts:');
    withHours.forEach((x, i) => lines.push((i + 1) + '. ' + x.quDisplay + ' — ' + fmtHours(x.studioHours) + hoursExtra(x) + ' — ' + afterQu(x.text)));
  }
  if (toCheck.length) {
    lines.push('');
    lines.push("🟡 *Studio hours need a check* — the quote's figures don't add up clearly, so nothing was posted:");
    toCheck.forEach((x, i) => lines.push((i + 1) + '. ' + x.quDisplay + ' — ' +
      x.hoursToCheck.map((f) => fmtHours(f.hours) + (f.optional ? ' optional' : '') + ' ("' + f.line + '")').join(' + ')));
  }
  if (noHours.length) {
    lines.push('');
    lines.push('⚪ *No studio hours on the quote* (no reply posted): ' + noHours.map((x) => x.quDisplay).join(', '));
  }
  if (already.length && mode !== 'live') {
    lines.push('');
    lines.push('↩️ Already replied to when posted: ' + already.map((x) => x.quDisplay).join(', '));
  }

  return lines.join('\n');
}

// First line of a post, trimmed, for a compact summary row.
function firstLine(text) {
  const t = String(text == null ? '' : text).split('\n')[0].trim();
  return t.length > 90 ? t.slice(0, 87) + '…' : t;
}
// ---- node glue ----
const meta = $('Set Oldest').first().json;
const CH = 'C1SJE7404';
const pages = meta.mode === 'live' ? [] : $('Fetch Newpost').all();
let msgs = meta.mode === 'live' && meta.post ? [Object.assign({}, meta.post, { channel: CH })] : [];
let maxTs = '';
for (const p of pages) {
  const arr = (p.json && p.json.messages) || [];
  for (const m of arr) {
    msgs.push(Object.assign({}, m, { channel: CH }));
    const t = String(m.ts || '');
    // Watermark advances to the newest ts READ, noise included, so a trailing chatter
    // post cannot stall it (the Workflow-1 watermark lesson).
    if (t && (maxTs === '' || Number(t) > Number(maxTs))) maxTs = t;
  }
}
const helpers = { isPostEngineer, extractQu, decodeEntities, tsToDate,
                  isIntakeWorkflow, submitterFromText, cleanWorkflowText };
const dateFilter = meta.mode === 'preview' ? meta.todayDate : null;
const candidates = gatherCandidates(msgs, dateFilter, helpers);
return [{ json: {
  mode: meta.mode, requester: meta.requester, dateLabel: meta.dateLabel,
  candidates: candidates, count: candidates.length,
  maxTs: maxTs, stateRow: meta.stateRow, oldWatermark: meta.oldWatermark
} }];

// Posty — QU parsing and status classification.
//
// This file is the single source of truth for how a Slack message becomes an index row.
// It is pasted verbatim into the Code nodes of Workflow 1 (index refresh) and Workflow 3
// (digest). Keep it dependency-free and side-effect-free so `./scripts/test-parser` can
// run it offline, and so the same code that is tested is the code that ships.
//
// Rules come from the build handoff §9. Do not tighten them without re-reading it:
// every shape below was taken from a real post in #newpostprojects or #releaseme.



// Handoff §9: case-insensitive, first match wins. {4,6} is deliberate headroom — real
// numbers are 5 digits but QU-50052 exists and the range is not contiguous. Do not
// narrow to {5}. The separator is not reliably a slash: space, dash, double space and
// underscore all occur, hence the character class. `QU_13577` is real and appears in both
// channels — before the underscore was added, that project was invisible to Posty
// entirely, on the intake side and the release side.
// Separators seen in real posts: dash, underscore, space, double space, none at all, and
// " - " with spaces on both sides. `QU - 17295 ref 17037` is real and appears in BOTH
// channels — before the surrounding whitespace was allowed, that project was invisible on
// the intake side and the release side alike.
//
// Widening this was diffed across all 1,658 backfilled messages: 2 newly matched, 0
// extractions changed. Re-run that diff before widening it further.
const QU_RE = /QU[\s]*[-_]?[\s]*(\d{4,6})/i;

// A synthetic key for a keyless project. Derived from the post's own ts, so it is unique,
// stable for the life of the row, and obviously not a real QU number at a glance.
//
// It deliberately cannot join an intake post to a separate release post — those are two
// different messages with no shared identifier, and guessing a link between them would be
// exactly the heuristic §9 warns against. It does not need to: releases now happen by
// reacting to the intake post, which resolves through the row's own source_ts.
// Handoff §9: (CANCELLED) anywhere in a #releaseme post means CANCELLED, not RELEASED.
// A naive diff scores it as released, which is wrong. Currently affects QU-17590.
const CANCELLED_RE = /\(\s*CANCELLED\s*\)/i;

// A Studio M / van recording is a production service (a recording session or a studio /
// mobile-van rental), NOT a releasable deliverable. Set by Tara 2026-09-08: once one of
// these is announced in #newpostprojects it is logged and left alone — it never enters the
// open pool to be chased, and it is never marked RELEASED. Matched by the phrases that
// name the service; the bare word "van" is deliberately excluded (it appears in "Van
// Digital" and elsewhere and over-matches). The status these rows carry is STUDIO_M below.
const STUDIO_M_RE = /studio\s*m|van\s*record|os\s*van/i;

function isStudioM(text) {
  return typeof text === 'string' && STUDIO_M_RE.test(text);
}

// The status value for those rows. A distinct state, neither OPEN (build-digest and the
// reminders only look at OPEN, so these drop out of both) nor RELEASED (so they never read
// as shipped to Accounting). The release path must treat it like RELEASED/CANCELLED and
// never overwrite it.
const STUDIO_M_STATUS = 'STUDIO M';

// Only these people announce projects. Set by Tara 2026-08-31 to keep channel chatter out
// of the index — a message from anyone else is not a project post, whatever it contains.
//
// This is a policy list, not a heuristic: it is maintained by a human who knows who the
// post engineers are, which is the only thing that reliably distinguishes an announcement
// from a conversation.
//
// **Add new post engineers here on their first day.** Until someone is on this list their
// posts are invisible to Posty — which is the intended behaviour, and also the way this
// list silently goes wrong. `isPostEngineer` is checked in the Workflow 2 classifier and in
// build-index.js, and a skipped message that DID carry a QU is logged with its code so the
// omission is discoverable in the execution list rather than silent.
const POST_ENGINEERS = {
  'U025597KZ':   'regie',
  'U029T6N7U':   'philip',
  'U026N6E1R':   'tara',
  'U04DLRCAA':   'glenn',
  'U6UAKUP08':   'whannie',
  'U026LMLM4':   'rico',
  'U026N9FV9':   'vener',
  'U026N7KR7':   'topet',
  'U026MTBLM':   'richard',
  'U026R9SUQ':   'eddie boy',
  'U08V83R45QV': 'elijah',
  'U08V3CKDGJF': 'howard',
};

function isPostEngineer(user) {
  return Object.prototype.hasOwnProperty.call(POST_ENGINEERS, String(user || '').trim());
}

// Names are for grouping the digest. A row whose author is not on the list — a historical
// row from before the allowlist, or a blank posted_by — groups under "unassigned" rather
// than being hidden, so nothing falls out of a total.
function engineerName(user) {
  const u = String(user || '').trim();
  return POST_ENGINEERS[u] || 'unassigned';
}

// The "New Project" intake form (Slack Workflow Builder) posts announcements as a bot, not
// as the human who filled it in — so the post has no `user`, carries a `bot_id`/`subtype:
// bot_message`, and would be dropped by both the noise filter and the post-engineer gate.
// These are the bot/app identities of the APPROVED intake workflows, maintained the same way
// as POST_ENGINEERS: a post from one of these, carrying a QU, is a project announcement.
//
// The message payload identifies the workflow by bot_id (always present) or app_id — NOT by
// the "Wf…" Workflow Builder id, which never appears on the post. **If the workflow is
// rebuilt from scratch its bot/app id changes and must be added here**, exactly like adding
// a new post engineer. Added 2026-09-10 when the form intake went live.
const INTAKE_WORKFLOW_BOTS = { 'B0C0US9CXU2': 'New Project form' };
const INTAKE_WORKFLOW_APPS = { 'A0C0YBR1GG4': 'New Project form' };

function isIntakeWorkflow(msg) {
  if (!msg || typeof msg !== 'object') return false;
  const bot = String(msg.bot_id || '').trim();
  const app = String(msg.app_id || '').trim();
  return Object.prototype.hasOwnProperty.call(INTAKE_WORKFLOW_BOTS, bot)
      || Object.prototype.hasOwnProperty.call(INTAKE_WORKFLOW_APPS, app);
}

// The form writes the person who submitted it as a leading Slack mention, e.g.
// "<@U026N6E1R> - *QU-*12345 / …". That mention is the real poster, and recording it as
// posted_by is what lets the react-to-release flow work for form posts too — the engineer
// who filed the project can react to release it, even though the message came from the bot.
function submitterFromText(text) {
  const m = String(text == null ? '' : text).match(/<@([A-Z0-9]+)>/);
  return m ? m[1] : '';
}

// The stored, human-readable form of a workflow post: drop the leading "<@submitter> -"
// (that is metadata, not the project) and the mrkdwn bold markers, leaving the clean project
// line "QU-12345 / Agency / …" that the index, the digest and the #releaseme repost all use.
function cleanWorkflowText(text) {
  return String(text == null ? '' : text)
    .replace(/^\s*<@[A-Z0-9]+>\s*[-–—:]?\s*/, '')
    .replace(/\*/g, '')
    .trim();
}

const NEWPOST_CHANNEL = 'C1SJE7404';
const RELEASEME_CHANNEL = 'CC9EG3K8C';

// Returns the QU digits as a string with no QU- prefix, or null when the message
// carries no code at all. String, not number: these are identifiers, and leading
// zeros would be lost the moment anything coerces them.
function extractQu(text) {
  if (typeof text !== 'string') return null;
  // Strip mrkdwn bold/italic asterisks first: the "New Project" intake form writes the code
  // as *QU-*12345, and the `*` between the separator and the digits would otherwise defeat
  // QU_RE. `*` is never part of a QU, so removing it is safe for ordinary posts too.
  const m = text.replace(/\*/g, '').match(QU_RE);
  return m ? m[1] : null;
}

// Slack's conversations.history escapes &, < and > in message text, so PC&V arrives as
// PC&amp;V. Stored raw, the Sheet fills with &amp; and is unpleasant to read, and so is
// any digest line built from it.
//
// Decode on the way IN, escape again on the way OUT (escapeForSlack, in resolve-release).
// The bytes Posty posts are therefore unchanged from the verified-working behaviour, while
// the stored copy is what a human would have typed.
//
// Order matters: &amp; must be decoded LAST, or "&amp;lt;" would turn into "<" instead of
// the literal "&lt;" it represents.
function decodeEntities(text) {
  if (typeof text !== 'string') return text;
  return text.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
}

// Every QU a #releaseme post closes.
//
// Usually one. But bulk release posts are common in the 2024 archive — several complete
// project lines in a single message — and "first match wins" (§9) then closes the first
// and leaves the rest open forever. That is 24 projects wrongly in the chase list.
//
// So on the RELEASE side, take every code. The one thing that must not be swept up is a
// BACK-REFERENCE: "(Addcost from QU-10317)" mentions an older project without releasing
// it, and closing it would tell Accounting to bill work that never shipped.
//
// Intake keeps first-match-wins: a post announcing several projects is a different
// question, and getting it wrong there invents projects rather than closing them.
const BACKREF_RE = /\b(?:from|ref|per|vs|supersedes|replaces|addcost\s+(?:from|of))\s*:?\s*$/i;

function extractReleasedQus(text) {
  if (typeof text !== 'string') return [];
  const s = text.replace(/\*/g, '');   // see extractQu: tolerate bold *QU-* on the release side too
  const re = new RegExp(QU_RE.source, 'gi');
  const found = [];
  let m;
  while ((m = re.exec(s)) !== null) {
    const before = s.slice(Math.max(0, m.index - 40), m.index);
    if (found.length && BACKREF_RE.test(before)) continue;
    if (found.indexOf(m[1]) === -1) found.push(m[1]);
  }
  return found;
}

// A QU- or QU_ prefix with no digits after it. This is the agreed posting convention:
// when a project has no code yet — pro bono, awaiting assignment, placeholder — the poster
// still writes "QU-" so the post is recognisably a project.
//
// A rule people are TOLD beats a rule inferred from punctuation. This replaced an earlier
// attempt that guessed from slash counts.
const QU_MARKER_RE = /QU[\s]*[-_]/i;

function hasQuMarker(text) {
  return typeof text === 'string' && QU_MARKER_RE.test(text);
}

// Synthetic key for a marked-but-uncoded project, derived from the post's own ts so it is
// unique and stable. Returns null for an implausible ts: a shared key would silently
// collapse every uncoded project onto one row.
function syntheticKey(ts) {
  const t = String(ts == null ? '' : ts).trim();
  if (!/^\d{6,}(\.\d+)?$/.test(t)) return null;
  return 'NOQU-' + t;
}

function isCancelled(text) {
  return typeof text === 'string' && CANCELLED_RE.test(text);
}

// Slack ts -> ISO date in Manila local time.
//
// The timezone is a judgment call the handoff does not make. Hit Productions is in
// Manila and age_days is counted in working days people recognise, so a post made at
// 07:00 Manila must date to that morning and not to the previous day in UTC. Asia/Manila
// is UTC+8 with no DST, so the fixed offset is exact rather than an approximation.
const MANILA_OFFSET_MS = 8 * 60 * 60 * 1000;

function tsToDate(ts) {
  if (ts === null || ts === undefined) return null;
  const seconds = Number(String(ts).split('.')[0]);
  if (!Number.isFinite(seconds)) return null;
  return new Date(seconds * 1000 + MANILA_OFFSET_MS).toISOString().slice(0, 10);
}

// Whole-day difference between two ISO dates. Both are already Manila-local calendar
// dates, so this is plain date arithmetic — no timezone maths, and no drift from the
// clock time of day the digest happens to run at.
function ageDays(postedDate, asOfDate) {
  if (!postedDate || !asOfDate) return null;
  const a = Date.parse(postedDate + 'T00:00:00Z');
  const b = Date.parse(asOfDate + 'T00:00:00Z');
  if (!Number.isFinite(a) || !Number.isFinite(b)) return null;
  return Math.round((b - a) / 86400000);
}

// Handoff §7 Workflow 3: >= 90 escalated, 45..89 flagged, < 45 omitted entirely.
// The boundaries are inclusive at 45 and at 90 — a project at exactly 45 days appears.
function bucketOf(age) {
  if (!Number.isFinite(age)) return null;
  if (age >= 90) return 'ESCALATED';
  if (age >= 45) return 'FLAGGED';
  return null;
}

// Turn one Slack message into an index row fragment. The caller supplies the channel so
// the CANCELLED rule stays scoped to #releaseme, where the handoff puts it.
function parseMessage(msg) {
  const text = decodeEntities((msg && msg.text) || '');
  const ts = msg && msg.ts;
  const channel = (msg && msg.channel) || '';
  let qu = extractQu(text);
  let synthetic = false;

  // Marked as a project but carrying no code -> track it under a synthetic key. It ages,
  // buckets and can be rocketed like anything else; when the real code arrives the poster
  // reposts with it.
  if (!qu && hasQuMarker(text)) {
    qu = syntheticKey(ts);
    synthetic = qu !== null;
  }

  // No QU digits and no QU- marker -> UNTRACKED. Never counted as open or as released.
  // Deliberately simple: a project is tracked when it carries a QU code, and not
  // otherwise. Codeless posts — placeholder codes, "QU-Not Available", foreign numbering,
  // "(NO Q-CODE)", pro bono — were briefly tracked under synthetic keys on 2026-08-31 and
  // that was reverted the same day in favour of a posting convention: post engineers write
  // a QU code, always.
  //
  // Nothing is lost by this. UNTRACKED rows still appear in the digest's "needs manual
  // check" section, so codeless work stays visible to a human — it simply is not counted,
  // aged or releasable, none of which can be done honestly without an identifier.
  if (!qu) {
    return {
      qu_number: null,
      synthetic: false,
      source_channel: channel,
      source_ts: String(ts),
      source_text: text,
      posted_date: tsToDate(ts),
      status: 'UNTRACKED',
    };
  }

  const cancelled = channel === RELEASEME_CHANNEL && isCancelled(text);

  return {
    qu_number: qu,
    synthetic,
    source_channel: channel,
    source_ts: String(ts),
    source_text: text,
    posted_date: tsToDate(ts),
    status: cancelled ? 'CANCELLED' : (channel === RELEASEME_CHANNEL ? 'RELEASED' : 'OPEN'),
  };
}

// Posty — Xero typo check.
//
// Pure logic for the scheduled check (Workflow 5) that validates each morning's
// #newpostprojects QU codes against Xero. The QU IS the Xero **Quote Number**
// (QuoteNumber = "QU-18030"), and Xero is where a project's quote is raised first —
// ahead of the announcement — so it is the authority. Was Airtable through
// 2026-09-16; switched to Xero 2026-09-17 (Tara) once the org's Xero connection was
// authorized. Pasted verbatim into the Code nodes of Workflow 5; dependency-free so
// scripts/test-xero runs it offline and the tested code is the shipped code.
//
// A quote is fetched per QU: GET /Quotes?QuoteNumber=QU-<digits>. A non-existent
// number comes back 200 with an empty Quotes array — that is the "not found" signal.
//
// Existence only. A QU that matches no Xero quote is a NOT_FOUND — a high-confidence typo,
// and the ONLY thing posted publicly (gently, in-thread). A customer/agency/producer match
// was tried and dropped 2026-09-17: Xero has no agency or producer field, and its customer
// (Contact) is the parent client (Unilever for a Knorr project), so it cried wolf. See
// classifyXero. Public messages say "the database", not "Xero" — Tara's call, 2026-09-17.
//
// Comparison is on DIGITS, never the raw reference string: the post side writes
// "QU-18077" / "QU_18077" / "QU - 18077" and Xero writes "QU-18077", and neither side's
// separator or prefix casing may cause a false "not found". See parse.js QU_RE.



// Digits of a QU reference, or null. Tolerant of both the post-side separator forms
// and the Xero-side canonical "QU-16867", and of a bare number with no prefix.
// {4,6} matches parse.js.
function quDigits(s) {
  if (typeof s !== 'string') return null;
  const m = s.match(/QU[\s]*[-_]?[\s]*(\d{4,6})/i);
  if (m) return m[1];
  const bare = s.match(/\b(\d{4,6})\b/);
  return bare ? bare[1] : null;
}


// A Xero field value as a display string.
function cellText(v) {
  if (Array.isArray(v)) return v.filter(x => x != null).join(', ');
  return v == null ? '' : String(v);
}

// Studio hours booked on a quote (Tara, 2026-09-28), replied in-thread on the post. Xero has no
// hours field: the hours are free text in a line item's Description, read LINE BY LINE. A line counts
// only when it STARTS with the figure ("80 Hrs. Studio Time", "- 28 hours (Packaged/Discounted)",
// "55 Hours Studio Rental") or names studio time right after it, and it or one of the 3 lines above
// it (the section heading) says studio. Backtested on 200 real quotes, 2026-09-28. Anything under Studio M / the mobile recording van is a separate service and never
// counts. The first version summed every "<n> hours" in any studio item, and QU-18269 came out at
// 152 = 80 studio + 24 and 48 from the van's booking terms ("at least 24 hours before…"). The real
// answer is 80 (fixtures/xero-lineitems-qu18269.json). Figures inside sentences never count. A studio
// item priced per hour with no figure counts its Quantity. Returns null when nothing qualifies, and
// null means say nothing publicly; it is never shown as zero.
const LEAD_HOURS_RE = /^[\s\-–•*]*(\d+(?:\.\d+)?)\s*(?:hours?|hrs?)\b/i;
// "studio", tolerating the misspellings that turn up in real quotes: "STUDO RENTAL: 25 Hours" (QU-18214,
// 2026-09-29) was missed because the I was missing.
const STUDIO_RE = /\bst(?:udio|udo|uido|idio|dio|uio)\b/i;
const NOT_STUDIO_RE = /st(?:udio|udo|uido|idio|dio|uio)\s*m\b|mobile/i;
const OPTIONAL_RE = /if the client opts|should (?:the )?client opt|\boptional\b/i;
// "30 Hours Studio Rental - TV", "80 Hours Studio Rental Package - Digital" -> the medium after the dash.
const MEDIUM_RE = /studio\s+(?:rental|time)(?:\s+package)?\s*[-\u2013]\s*([A-Za-z][A-Za-z\/ ]{0,20})$/i;
const MID_STUDIO_RE = /(\d+(?:\.\d+)?)\s*(?:hours?|hrs?)\.?\s+(?:of\s+)?studio\s+(?:time|rental)\b/i;
// Every studio-hours figure on the quote, with the line it came from. Only a quote with exactly ONE
// figure gets a public reply (Tara, 2026-09-28). Two or more (options, add-ons, a stray terms line)
// go to Tara's DM to check instead, because summing them is how QU-18269 read 152.
function studioHoursDetail(lineItems) {
  const figures = [];
  for (const li of (lineItems || [])) {
    const d = cellText(li && li.Description);
    if (/^\s*NOTE\b/i.test(d)) continue;                    // a terms note is never a booking
    let hit = false;
    // An optional offer ("If the client opts to include an additional dialect… 4 Hrs. Studio Time")
    // isn't booked. Its hours are shown as optional, never added (QU-18147, QU-18112). Only lines FROM
    // the optional phrase on are optional: booked hours above fine print like "should client opt to
    // use VO recording…" stay booked (QU-18033 shape).
    const lines = d.split('\n').map((l) => l.trim()).filter(Boolean);
    const optFrom = lines.findIndex((l) => OPTIONAL_RE.test(l));
    const optional = optFrom !== -1;
    lines.forEach((line, i) => {
      // "80 Hrs. Studio Time" / "- 28 hours" lead with the figure; "Audio Engineer / 20 Hrs. Studio
      // Time" names studio time right after it. Anything else mid-sentence never counts.
      const m = line.match(LEAD_HOURS_RE) || line.match(MID_STUDIO_RE);
      if (!m) return;
      // Context = this line plus the 3 before it, which covers the headings seen in 200 real quotes:
      // "STUDIO RENTAL:", "STUDIO RENTAL" / "STUDIO RENTAL -" with no colon, and a sub-heading in
      // between ("STUDIO RENTAL ⏎ Packaged/Discounted: ⏎ - 20 hours").
      const ctx = lines.slice(Math.max(0, i - 3), i + 1).join(' ');
      if (!STUDIO_RE.test(ctx) || NOT_STUDIO_RE.test(ctx)) return;
      const medium = (line.match(MEDIUM_RE) || [])[1];
      figures.push({ hours: Number(m[1]), line: line.slice(0, 80), optional: optFrom !== -1 && i >= optFrom, medium: medium ? medium.trim() : '' }); hit = true;
    });
    if (!hit && STUDIO_RE.test(d) && !NOT_STUDIO_RE.test(d) && /per\s*hour|hourly|\/\s*hr\b/i.test(d) && Number(li.Quantity) > 0) {
      figures.push({ hours: Number(li.Quantity), line: d.split('\n')[0].trim().slice(0, 60) + ' × ' + li.Quantity, optional: optional, medium: '' });
    }
  }
  const r2 = (n) => Math.round(n * 100) / 100;
  const booked = figures.filter((f) => !f.optional);
  const opt = figures.filter((f) => f.optional);
  const total = booked.length ? r2(booked.reduce((t, f) => t + f.hours, 0)) : null;
  const optional = opt.length ? r2(opt.reduce((t, f) => t + f.hours, 0)) : null;
  // Public when the booked hours read unambiguously: one figure, or one per medium (TV + Radio …),
  // shown as a breakdown. Anything else goes to Tara to check (Tara, 2026-09-28).
  const media = booked.map((f) => f.medium.toLowerCase());
  const split = booked.length > 1 && media.every(Boolean) && new Set(media).size === media.length;
  const clear = booked.length === 1 || split;
  return { figures: figures, total: total, optional: optional, clear: clear,
           breakdown: split ? booked.map((f) => f.hours + ' ' + f.medium).join(' + ') : '' };
}
function studioHours(lineItems) { return studioHoursDetail(lineItems).total; }

// Build the {digits -> quote} lookup from the Xero responses. Each response is the body
// of one GET /Quotes?QuoteNumber=… call, so it carries a Quotes array with 0 or 1 (rarely
// more) quotes. A candidate whose QU is absent here is NOT_FOUND. DELETED quotes are
// dropped — a deleted quote is not a live project and must not vouch for a mistyped QU.
function indexQuotes(responses) {
  const byDigits = {};
  for (const resp of (responses || [])) {
    const quotes = (resp && (resp.Quotes || (resp.body && resp.body.Quotes))) || [];
    for (const q of quotes) {
      if (!q) continue;
      const status = cellText(q.Status).toUpperCase();
      if (status === 'DELETED') continue;
      const d = quDigits(cellText(q.QuoteNumber));
      if (!d) continue;
      if (!(d in byDigits)) {
        byDigits[d] = {
          quoteNumber: cellText(q.QuoteNumber),
          client: q.Contact ? cellText(q.Contact.Name) : '',
          status: cellText(q.Status),
          hours: studioHoursDetail(q.LineItems),
        };
        const h = byDigits[d].hours;
        // Public only when the booked hours are clear; otherwise Tara checks them (hoursToCheck).
        byDigits[d].studioHours = h.clear ? h.total : null;
        byDigits[d].hoursToCheck = h.figures.length && !h.clear ? h.figures : null;
      }
    }
  }
  return byDigits;
}

// Xero answering is not the same as Xero saying "no such quote". A real lookup always returns a
// Quotes array, empty when the number doesn't exist. Anything else (an expired connection, a 401,
// a 5xx, a rate limit) has no Quotes array, and indexQuotes would read that as "not found" and
// post a false typo flag on every post (2026-09-28). This returns the failed responses so the run
// can stop before posting anything. The first one's error text goes to Tara.
function failedLookups(responses) {
  const bad = [];
  for (const resp of (responses || [])) {
    const q = resp && (resp.Quotes || (resp.body && resp.body.Quotes));
    if (!Array.isArray(q)) bad.push(resp);
  }
  return bad;
}

function xeroDownText(bad, ctx) {
  const c = ctx || {};
  const r = bad[0] || {};
  const why = String(r.Detail || r.Title || r.message || r.error || (r.Status ? 'HTTP ' + r.Status : '') || 'no answer')
    .replace(/\s+/g, ' ').slice(0, 140);
  return '*Typo check — ' + (c.dateLabel || 'today') + '*\n' +
    "⚠️ Couldn't reach Xero (" + bad.length + ' of ' + (c.checked || bad.length) + ' lookups failed: ' + why + ').\n' +
    (c.mode === 'preview'
      ? 'Nothing was checked.'
      : 'Nothing was posted, and these posts will be checked again next run.') +
    '\nIf this repeats, the Xero connection needs re-authorizing: someone with Standard or Adviser ' +
    'access in Xero clicks *Connect* on the n8n "Xero account" credential.';
}

// Has Posty already replied in this post's thread? Every post is checked the moment it's posted
// (live) AND again by the 09:00/17:00 safety-net runs, and Slack sometimes delivers an event twice,
// so the thread itself is the record of "done". resp is one conversations.replies body; messages[0]
// is the post, the rest are replies. A failed read counts as not replied, so the post is still checked.
const POSTY_USER = 'U0BTV2PGDSM', POSTY_BOT = 'B0BTLTJQD6F';
function alreadyReplied(resp) {
  if (!resp || resp.ok !== true) return false;
  return (resp.messages || []).slice(1).some((m) => m && (m.user === POSTY_USER || m.bot_id === POSTY_BOT));
}

// One post that carries a real QU. Built by gatherCandidates. Shape:
//   { qu, quDisplay, ts, channel, text }
//
// helpers is the parse.js surface, injected so this module stays require-free when pasted
// into an n8n node: { isPostEngineer, extractQu, decodeEntities, tsToDate, isIntakeWorkflow,
// submitterFromText, cleanWorkflowText }.
//
// A post counts as a project either because a post engineer wrote it OR because it came from
// the "New Project" intake form — which now posts as a bot with no `user`, so without the
// isIntakeWorkflow branch the typo check would silently skip every form post, i.e. the whole
// point of the check on the primary intake path. Form posts contribute the cleaned line and
// the submitter is irrelevant here (we only validate the QU + client).
//
// dateFilter is optional. The window is really bounded by the Slack `oldest` the caller
// fetched with — either midnight today (preview) or the since-last-checked watermark
// (scheduled). Pass a YYYY-MM-DD to additionally keep only that day's posts; pass null to
// keep everything the fetch returned, which is what the watermark path wants (its window
// can legitimately span more than one day if a run was missed).
function gatherCandidates(messages, dateFilter, helpers) {
  const out = [];
  const seen = {};
  for (const m of (messages || [])) {
    if (!m) continue;
    const wf = typeof helpers.isIntakeWorkflow === 'function' && helpers.isIntakeWorkflow(m);
    let text, poster;
    if (wf) {
      // A form post comes from the bot; the person to tag is the submitter it names.
      poster = typeof helpers.submitterFromText === 'function' ? helpers.submitterFromText(m.text) : '';
      text = typeof helpers.cleanWorkflowText === 'function' ? helpers.cleanWorkflowText(m.text) : (m.text || '');
    } else {
      if (m.subtype) continue;                       // joins, leaves, non-intake bot posts
      if (!helpers.isPostEngineer(m.user)) continue; // only announcements, excludes Posty
      text = helpers.decodeEntities(m.text || '');
      poster = m.user || '';
    }
    const qu = helpers.extractQu(text);              // null for no-code / QU- placeholder
    if (!qu) continue;
    if (dateFilter && helpers.tsToDate(m.ts) !== dateFilter) continue; // preview only
    if (seen[qu]) continue;                          // same code posted twice, check once
    seen[qu] = true;
    out.push({
      qu: qu,
      quDisplay: 'QU-' + qu,
      ts: String(m.ts),
      channel: m.channel || '',
      text: text,
      poster: /^[UW][A-Z0-9]+$/.test(String(poster || '')) ? String(poster) : '',
    });
  }
  return out;
}

// Existence-only against Xero. A Xero quote has no agency or producer field, and its
// customer (Contact) is the parent client (Unilever for a Knorr project), so matching it to
// the post cried wolf constantly — dropped 2026-09-17 (Tara). The only Xero signal is
// whether the QU is a real quote number at all: found -> ok, absent -> notFound (the public
// typo flag). `mismatch` is kept empty so the summary and findings count stay uniform.
function classifyXero(candidates, byDigits) {
  const notFound = [], ok = [];
  for (const c of (candidates || [])) {
    if (byDigits[c.qu]) {
      const q = byDigits[c.qu], h = q.hours || {};
      ok.push(Object.assign({}, c, { studioHours: q.studioHours, hoursToCheck: q.hoursToCheck || null,
        hoursBreakdown: q.studioHours != null ? (h.breakdown || '') : '', hoursOptional: q.studioHours != null ? h.optional : null }));
    }
    else notFound.push(c);
  }
  return { notFound: notFound, mismatch: [], ok: ok };
}

// The public in-thread reply. mrkdwn (single-asterisk bold). Gentle by design: it
// asks for a check, it does not assert the poster is wrong — Xero can lag a little,
// and a false accusation in the intake channel is exactly what erodes trust in Posty.
// "the database" rather than "Xero" — the source is kept generic in what people see
// (Tara, 2026-09-17). Only the messages use this wording; the code still checks Xero.
// Public replies tag the poster so they get a notification: a thread reply alone only reaches
// people following the thread, and a form post's thread belongs to the bot (Tara, 2026-09-28).
function tag(c) { return c && c.poster ? '<@' + c.poster + '> ' : ''; }

function flagText(c) {
  // Specific next steps (Tara, 2026-09-28): repost with the right QU, and leave the old post. Form
  // posts can't be deleted by engineers, Tara removes them, and there's no rush: the repost has a
  // different QU, so it is tracked on its own either way.
  return tag(c) + c.quDisplay + " isn't in the database — mind double-checking? " +
    "If it's a typo, please post the project again with the correct QU. " +
    "No need to delete this one, Tara will remove it. If the QU is correct, just ignore this.";
}

// The public studio-hours reply, for a found quote that names its hours. Same wording rule as
// flagText: "the quote", never "Xero".
function fmtHours(h) { return h + (h === 1 ? ' hr' : ' hrs'); }
// "(30 TV + 10 Radio)" for a media split, "(+ 4 hrs optional)" for an optional offer on the quote.
function hoursExtra(c) {
  return (c.hoursBreakdown ? ' (' + c.hoursBreakdown + ')' : '') +
    (c.hoursOptional != null ? ' (+ ' + fmtHours(c.hoursOptional) + ' optional)' : '');
}
function hoursText(c) {
  return tag(c) + '🎧 Studio hours based on ' + c.quDisplay + ': *' + fmtHours(c.studioHours) + '*' + hoursExtra(c);
}

// The post text with the leading QU token stripped, so a summary line can read
// "QU-71498 — OMT / Producer / Title" without repeating the code.
function afterQu(text) {
  const t = firstLine(text);
  const idx = t.indexOf('/');
  return idx !== -1 ? t.slice(idx + 1).trim() : t;
}

// Tara's DM summary. mode is 'scheduled' or 'preview'. In preview nothing was posted
// publicly, so the summary says what *would* post. res is classify()'s result.
function buildTaraSummary(res, ctx) {
  const c = ctx || {};
  // live = one post checked the moment it was posted (Workflow 2 calls in, 2026-09-28).
  const mode = c.mode === 'preview' || c.mode === 'live' ? c.mode : 'scheduled';
  const checked = c.checked == null ? 0 : c.checked;
  const already = c.already || [];
  const day = c.dateLabel || '';
  const lines = [];
  const would = mode === 'preview';

  if (mode === 'live') {
    const x = res.notFound[0] || res.ok[0];
    lines.push('*Typo check — new post' + (x ? ', ' + x.quDisplay : '') + '*');
  } else {
    lines.push(would
      ? '*Typo check — ' + (day || 'today') + '*  (preview — nothing posted publicly)'
      : '*Typo check — ' + (day || 'today') + '*');
    // Runs twice a day on a watermark, so a scheduled run covers "since the last check", not
    // "this morning" (the 17:00 run said "from this morning" until 2026-09-26). Posts already
    // answered when they were posted are counted separately and never replied to twice.
    lines.push('Checked ' + checked + ' post' + (checked === 1 ? '' : 's') +
      (would ? ' posted today' : ' since the last check') +
      (already.length ? ' (' + already.length + ' more already replied to when posted)' : '') + '.');
  }

  if (res.notFound.length) {
    lines.push('');
    lines.push(would
      ? "🔴 *Not in the database* — I'd reply on these posts:"
      : '🔴 *Not in the database* — replied on these posts:');
    res.notFound.forEach((x, i) => lines.push((i + 1) + '. ' + x.quDisplay + ' — ' + afterQu(x.text)));
  }

  if (!res.notFound.length && checked) {
    lines.push('');
    lines.push(mode === 'live' ? '✅ The QU is in the database.' : '✅ All clear — every QU is in the database.');
  }

  const withHours = res.ok.filter((x) => x.studioHours != null);
  const toCheck = res.ok.filter((x) => x.hoursToCheck);
  const noHours = res.ok.filter((x) => x.studioHours == null && !x.hoursToCheck);
  if (withHours.length) {
    lines.push('');
    lines.push(would
      ? "🎧 *Studio hours* — I'd reply on these posts:"
      : '🎧 *Studio hours* — replied on these posts:');
    withHours.forEach((x, i) => lines.push((i + 1) + '. ' + x.quDisplay + ' — ' + fmtHours(x.studioHours) + hoursExtra(x) + ' — ' + afterQu(x.text)));
  }
  if (toCheck.length) {
    lines.push('');
    lines.push("🟡 *Studio hours need a check* — the quote's figures don't add up clearly, so nothing was posted:");
    toCheck.forEach((x, i) => lines.push((i + 1) + '. ' + x.quDisplay + ' — ' +
      x.hoursToCheck.map((f) => fmtHours(f.hours) + (f.optional ? ' optional' : '') + ' ("' + f.line + '")').join(' + ')));
  }
  if (noHours.length) {
    lines.push('');
    lines.push('⚪ *No studio hours on the quote* (no reply posted): ' + noHours.map((x) => x.quDisplay).join(', '));
  }
  if (already.length && mode !== 'live') {
    lines.push('');
    lines.push('↩️ Already replied to when posted: ' + already.map((x) => x.quDisplay).join(', '));
  }

  return lines.join('\n');
}

// First line of a post, trimmed, for a compact summary row.
function firstLine(text) {
  const t = String(text == null ? '' : text).split('\n')[0].trim();
  return t.length > 90 ? t.slice(0, 87) + '…' : t;
}
// ---- node glue ----
const g = $('Gather').first().json;
const all = g.candidates || [];
const allResponses = $('Fetch Quote').all().map(function (it) { return it.json; });
// Skip posts Posty already replied to (checked live when posted, or a duplicate Slack event).
// Fetch Replies and Fetch Quote both run once per candidate, in order, so index i pairs them.
const threads = $('Fetch Replies').all().map(function (it) { return it.json; });
const already = [], candidates = [], responses = [];
all.forEach(function (c, i) {
  if (alreadyReplied(threads[i])) already.push(c);
  else { candidates.push(c); responses.push(allResponses[i]); }
});
// A live post that is already answered is a repeat delivery: say nothing, DM nothing.
if (g.mode === 'live' && !candidates.length) {
  return [{ json: { mode: g.mode, requester: g.requester, summary: '', flags: [], notFound: 0, mismatch: 0, findings: 0, already: already.length } }];
}
// Xero didn't answer properly for at least one post: post NOTHING (a missing answer would read as
// "not in the database" on every post), tell Tara, and leave the watermark where it was so the
// next run re-checks these posts. Advance Watermark reads xero_down below.
const bad = failedLookups(responses);
if (bad.length) {
  return [{ json: { mode: g.mode, requester: g.requester, xero_down: true,
    summary: xeroDownText(bad, { mode: g.mode, checked: candidates.length, dateLabel: g.dateLabel }),
    flags: [], notFound: 0, mismatch: 0, findings: 0 } }];
}
const byDigits = indexQuotes(responses);
const res = classifyXero(candidates, byDigits);
const summary = buildTaraSummary(res, { mode: g.mode, checked: candidates.length, dateLabel: g.dateLabel, already: already });
const flags = res.notFound.map(function (c) { return { channel: c.channel, ts: c.ts, text: flagText(c) }; });
// Studio hours from the quote, replied in-thread on each found post that names them (2026-09-28).
res.ok.forEach(function (c) {
  if (c.studioHours != null) flags.push({ channel: c.channel, ts: c.ts, text: hoursText(c) });
});
const findings = res.notFound.length + res.mismatch.length;
return [{ json: {
  mode: g.mode, requester: g.requester,
  summary: summary, flags: flags,
  notFound: res.notFound.length, mismatch: res.mismatch.length, findings: findings
} }];

const j = $('Classify').first().json;
// Scheduled and live runs post publicly; a preview ("typos") never does.
if (j.mode !== 'scheduled' && j.mode !== 'live') return [];
return (j.flags || []).map(function (f) { return { json: f }; });

// Advance the since-last-checked watermark — scheduled runs only. maxTs is the newest ts
// actually read this run; write it only if it moved past the old mark. Preview runs, quiet
// runs (no messages) and a missing state row all no-op, leaving the watermark untouched.
const g = $('Gather').first().json;
if (g.mode !== 'scheduled') return [];
// Xero was unreachable this run, so nothing was checked: keep the old mark and re-check next run.
// Classify runs before this node (v1 order: the Has Candidates branch is wired first off Gather),
// and it doesn't run at all when there were no candidates.
let down = false;
try { down = $('Classify').isExecuted && Boolean($('Classify').first().json.xero_down); } catch (e) { down = false; }
if (down) return [];
const maxTs = String(g.maxTs || '');
if (!maxTs) return [];
if (g.oldWatermark && Number(maxTs) <= Number(g.oldWatermark)) return [];
if (g.stateRow === '' || g.stateRow == null) return [];
return [{ json: { row_number: g.stateRow, last_typo_ts: maxTs } }];

const g = $('Gather').first().json;
return (g.candidates || []).map(function (c) {
  return { json: { quDisplay: c.quDisplay, qu: c.qu, text: c.text, ts: c.ts, channel: c.channel } };
});
